import { readFileSync } from 'node:fs';

const NEON_HOST = 'ep-little-flower-abh704gp-pooler.eu-west-2.aws.neon.tech';
const CONN_STR = `postgresql://neondb_owner:npg_rXSs1lnRzg9V@${NEON_HOST}/neondb?sslmode=require`;

async function runQuery(sql) {
  const res = await fetch(`https://${NEON_HOST}/sql`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Neon-Connection-String': CONN_STR,
    },
    body: JSON.stringify({ query: sql }),
  });
  const json = await res.json();
  if (json.message || json.code) throw new Error(`SQL error: ${json.message} (${json.code})\nStatement: ${sql.slice(0, 100)}`);
  return json;
}

const schemaSql = readFileSync('/tmp/schema.sql', 'utf8');

// Split on semicolons but preserve function bodies (dollar-quoted strings)
// Simple approach: split on lines starting with -- and use double-newline boundaries
// Actually split on ";\n" outside of dollar-quoted blocks
function splitStatements(sql) {
  const stmts = [];
  let current = '';
  let inDollarQuote = false;
  let dollarTag = '';
  let i = 0;

  while (i < sql.length) {
    // Check for dollar-quote start/end
    if (!inDollarQuote) {
      const dollarMatch = sql.slice(i).match(/^\$[^$]*\$/);
      if (dollarMatch) {
        dollarTag = dollarMatch[0];
        inDollarQuote = true;
        current += dollarTag;
        i += dollarTag.length;
        continue;
      }
    } else {
      if (sql.slice(i).startsWith(dollarTag)) {
        current += dollarTag;
        i += dollarTag.length;
        inDollarQuote = false;
        dollarTag = '';
        continue;
      }
    }

    const ch = sql[i];
    current += ch;

    if (!inDollarQuote && ch === ';') {
      const trimmed = current.trim();
      if (trimmed && trimmed !== ';') {
        stmts.push(trimmed);
      }
      current = '';
    }
    i++;
  }
  if (current.trim()) stmts.push(current.trim());
  return stmts;
}

const statements = splitStatements(schemaSql).filter(s => !s.startsWith('--') && s.length > 1);

console.log(`Running ${statements.length} statements...`);

let ok = 0;
for (const stmt of statements) {
  try {
    await runQuery(stmt);
    ok++;
    process.stdout.write('.');
  } catch (err) {
    console.error(`\nFailed: ${err.message}`);
    process.exit(1);
  }
}
console.log(`\nDone! ${ok} statements executed successfully.`);

